import csv
path='/tmp/weoapr2025all.xls'
with open(path, 'r', encoding='utf-16-le') as f:
    reader=csv.reader(f, delimiter='\t')
    header=next(reader)
    header=[h.strip() for h in header]
    idx={name:i for i,name in enumerate(header)}
    data={}
    for row in reader:
        if not row:
            continue
        if len(row)<len(header):
            row += ['']*(len(header)-len(row))
        if row[idx['Country']]=='Georgia' and row[idx['WEO Subject Code']] in ('NGDP_R','NGDP_RPCH'):
            code=row[idx['WEO Subject Code']]
            data[code]=row
    for code in ('NGDP_R','NGDP_RPCH'):
        row=data[code]
        vals={y: row[idx[str(y)]] for y in range(2000, 2028)}
        # check missing
        missing=[y for y,v in vals.items() if v in ('','n/a','NA',None)]
        print(code, 'missing', missing[:5], 'count', len(missing))
        # print 2000-2005
        print({y: vals[y] for y in range(2000,2005)})
